// File: ProductList.js
import React from "react";
import Product from "./Product";
import { menuCategories } from "./useProductLogic";
import useProductLogic from "./useProductLogic";
import "./ProductList.css"; // Nhúng file CSS vào đây

function ProductList({ category, setCategory, brand, setBrand }) {
  const {
    filteredProducts,
    priceRange, setPriceRange,
    currentPage, setCurrentPage,
    totalPages,
    productsPerPage
  } = useProductLogic(category, setCategory, brand, setBrand);

  return (
    <div className="container-fluid mt-4 mb-5 px-4">
      
      {/* BỘ LỌC NGANG */}
      <div className="row mb-4">
        <div className="col-12">
          <h4 className="fw-bold text-uppercase mb-3 product-list-title">
            Tất cả sản phẩm
          </h4>
          <p className="text-muted mb-2">Bộ lọc sản phẩm</p>
          
          <div className="d-flex gap-3">
            <select className="form-select w-auto shadow-sm" value={priceRange} onChange={(e) => setPriceRange(e.target.value)}>
              <option value="">Chọn mức giá</option>
              <option value="duoi10">Dưới 10 triệu</option>
              <option value="10den20">Từ 10 - 20 triệu</option>
              <option value="tren20">Trên 20 triệu</option>
            </select>

            <select className="form-select w-auto shadow-sm" value={category} onChange={(e) => setCategory(e.target.value)}>
              <option value="">Loại</option>
              {menuCategories.map(menu => (
                <option key={menu.id} value={menu.id}>{menu.name}</option>
              ))}
            </select>

            <select className="form-select w-auto shadow-sm" value={brand} onChange={(e) => setBrand(e.target.value)}>
              <option value="">Thương hiệu</option>
              <option value="Apple">Apple</option>
              <option value="Asus">Asus</option>
              <option value="Samsung">Samsung</option>
              <option value="Intel">Intel</option>
              <option value="AMD">AMD</option>
              <option value="MSI">MSI</option>
              <option value="Logitech">Logitech</option>
              <option value="Corsair">Corsair</option>
            </select>
          </div>
        </div>
      </div>

      <div className="row">
        {/* SIDEBAR TRÁI */}
        <div className="col-md-3 mb-4">
          <div className="card shadow-sm border-0 rounded-0">
            <div className="list-group list-group-flush">
              <button
                type="button"
                className={`list-group-item list-group-item-action fw-bold py-2 ${category === "" ? "text-primary" : "text-dark"}`}
                onClick={() => { setCategory(""); setBrand(""); }}
              >
                Tất cả sản phẩm
              </button>
              
              {menuCategories.map((menu) => (
                <button
                  key={menu.id}
                  type="button"
                  className={`list-group-item list-group-item-action border-0 py-1 d-flex justify-content-between align-items-center category-menu-item ${category === menu.id ? "text-primary fw-bold" : "text-muted"}`}
                  onClick={() => { setCategory(menu.id); setBrand(""); }}
                >
                  <span>{menu.name}</span>
                  <small>›</small>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* LƯỚI SẢN PHẨM TRƯỢT SLIDE NGANG */}
        <div className="col-md-9 d-flex flex-column justify-content-between product-slider-container">
          <div className="product-slider-wrapper">
            <div 
              className="product-slider-track" 
              style={{ 
                transform: `translateX(-${currentPage * 100}%)`, 
                width: `${totalPages * 100}%` 
              }}
            >
              {[...Array(totalPages)].map((_, pageIndex) => {
                const start = pageIndex * productsPerPage;
                const pageProducts = filteredProducts.slice(start, start + productsPerPage);

                return (
                  <div key={pageIndex} style={{ width: `${100 / totalPages}%` }} className="px-1">
                    <div className="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 m-0">
                      {pageProducts.length > 0 ? (
                        pageProducts.map((item) => (
                          <div className="col" key={item.id}>
                            <Product data={item} />
                          </div>
                        ))
                      ) : (
                        <div className="col-12 text-center mt-5">
                          <p className="text-muted fs-5">Không có sản phẩm nào khớp với bộ lọc của bạn.</p>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* CHẤM TRÒN PHÂN TRANG */}
          {totalPages > 1 && (
            <div className="d-flex justify-content-center align-items-center gap-2 mt-5">
              {[...Array(totalPages)].map((_, index) => (
                <button
                  key={index}
                  type="button"
                  onClick={() => setCurrentPage(index)}
                  className={`dot-pagination-btn ${index === currentPage ? "active" : ""}`}
                  title={`Trang ${index + 1}`}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default ProductList;
